  async ngOnInit() {
    this.charge_codes.set(await nextValueFrom(this._state.charge_codes) || []);
  }
  newCode() {
    this.charge_codes.update((l) => {
      l.push("");
      return l;
    });
  }
  removeCode(index) {
    this.charge_codes.update((l) => {
      l.splice(index, 1);
      return l;
    });
  }
